const expectedByName = new Map(manifest.map((entry) => [entry[1], entry]));
const rowSchema = z.object({
  type: z.string(), name: z.string(), tbl_name: z.string(), sql: z.string().nullable(),
}).strict();

/** Read-only, bounded exact canonical49 schema proof, not complete cohort admission. */
export function assertCanonical49Schema(database: Database): void {
  // The longest original declaration is 8,465 UTF-8 bytes. A 16-KiB
  // representation ceiling permits harmless layout changes without returning
  // arbitrarily large foreign SQL text to JavaScript. One extra row detects
  // overflow; no partial schema can prove completeness.
  const parsed = rowSchema.array().safeParse(database.query(
    "SELECT type,CASE WHEN length(CAST(name AS BLOB))<=128 THEN name ELSE NULL END AS name,CASE WHEN length(CAST(tbl_name AS BLOB))<=128 THEN tbl_name ELSE NULL END AS tbl_name,CASE WHEN length(CAST(sql AS BLOB))<=16384 THEN sql ELSE NULL END AS sql FROM sqlite_schema WHERE lower(substr(name,1,7))!='sqlite_' ORDER BY type,name LIMIT 540",
  ).all());
  if (!parsed.success) throw new Error("STATE_CANONICAL49_SCHEMA_INVALID");
  const rows = parsed.data;
  const byName = new Map(rows.map((row) => [row.name, row]));
  if (rows.length > manifest.length || byName.size !== rows.length
    || rows.some((row) => !expectedByName.has(row.name))) {
    throw new Error("STATE_CANONICAL49_SCHEMA_UNEXPECTED");
  }
  for (const [type, name, table, expectedDigest] of manifest) {
    const row = byName.get(name);
    if (row === undefined) throw new Error("STATE_CANONICAL49_SCHEMA_MISSING:" + name);
    let valid = false;
    if (row.type === type && row.tbl_name === table && row.sql !== null) {
      try {
        valid = createHash("sha256").update(normalizeSchemaSql(row.sql)).digest("hex") === expectedDigest;
      } catch { /* Malformed foreign SQL never becomes an admitted definition. */ }
    }
    if (!valid) throw new Error("STATE_CANONICAL49_SCHEMA_INVALID:" + name);
  }
}
